import{_ as o,o as t,c as a,a6 as r}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Desenvolva o TikTools","description":"","frontmatter":{"title":"Desenvolva o TikTools","docId":"developer.overview","translationKey":"developer.overview","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"1ee65a70172f8154eeaf60fb1a3069192769582a4ef264426d0aefaf346e8003","translationRevision":"bde2a126f6cc2d16e7fabbe663b36b25d9a32d8f8251a079bd4f1fdf559f574c","order":0},"headers":[],"relativePath":"pt/developer/index.md","filePath":"pt/developer/index.md","lastUpdated":1794611623000}'),d={name:"pt/developer/index.md"};function s(i,e,n,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="develop-tiktools" tabindex="-1">Desenvolva o TikTools <a class="header-anchor" href="#develop-tiktools" aria-label="Permalink to &quot;Desenvolva o TikTools {#develop-tiktools}&quot;">​</a></h1><p>O TikTools mantém um único AppCore nativo por trás de operações de controle tipadas. Vue renderiza as interfaces de desktop, navegador local e controlador; Winit/Wry é responsável pelas janelas de desktop. A CLI e o SDK usam as mesmas operações. Comece pela <a href="./setup.html">configuração de desenvolvimento</a>, depois escolha o menor ciclo que cubra sua alteração.</p><h2 id="choose-an-entry-point" tabindex="-1">Escolha um ponto de entrada <a class="header-anchor" href="#choose-an-entry-point" aria-label="Permalink to &quot;Escolha um ponto de entrada {#choose-an-entry-point}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trabalho</th><th>Ponto de entrada</th><th>O que comprova</th></tr></thead><tbody><tr><td>Componentes e stores Vue</td><td>Vite, Vitest e o ControlClient injetado</td><td>Comportamento da interface; sem validação de janela nativa.</td></tr><tr><td>Integração de desktop</td><td><code>bun run start</code></td><td>Integração de WebView e IPC de desenvolvimento.</td></tr><tr><td>Serviços nativos</td><td>Testes Cargo específicos</td><td>Contratos do núcleo, persistência e comportamento de serviços.</td></tr><tr><td>Acesso por navegador sem interface gráfica no host</td><td><code>bun run dev</code></td><td>Um host nativo, adaptador local e Vite com pareamento.</td></tr><tr><td>Documentação</td><td><code>bun scripts/task.ts docs dev</code></td><td>Markdown e compilação isolada do VitePress.</td></tr><tr><td>Demonstração pública</td><td>Entrada de demonstração separada e transporte simulado</td><td>Cenários determinísticos fictícios, não os serviços externos.</td></tr></tbody></table><h2 id="source-ownership" tabindex="-1">Responsabilidade pelo código-fonte <a class="header-anchor" href="#source-ownership" aria-label="Permalink to &quot;Responsabilidade pelo código-fonte {#source-ownership}&quot;">​</a></h2><ul><li><code>crates/tiktools-core</code>: serviços, operações e SQLite. Não depende de uma WebView.</li><li><code>crates/tiktools-control-api</code>: registro, roteamento JSON-RPC, IPC e descoberta.</li><li><code>crates/tiktools-desktop</code>: Winit/Wry, ponte com a thread de interface, ciclo de vida e recursos empacotados.</li><li><code>src/web/app</code>: inicialização, roteador e estrutura da interface. <code>pages</code> compõe <code>widgets</code> e <code>features</code>; <code>entities</code> é responsável por stores/contratos de domínio; <code>shared</code> contém interface e infraestrutura reutilizáveis.</li><li><code>src/automation/contracts/generated</code>: contratos de eventos do frontend versionados e gerados a partir de Rust. Não redigite esses esquemas em uma demonstração ou guia.</li><li><code>packages</code>: os pacotes TypeScript existentes de SDK/interface para plugins. Implementações de plugins ficam no repositório externo de plugins.</li></ul><h2 id="contribution-boundary" tabindex="-1">Limites de contribuição <a class="header-anchor" href="#contribution-boundary" aria-label="Permalink to &quot;Limites de contribuição {#contribution-boundary}&quot;">​</a></h2><p>Mantenha explícitos os pontos de entrada nativo, de navegador local, controlador remoto e demonstração. A ausência de um host nativo é um erro em uma entrada real; ela não deve selecionar silenciosamente uma simulação. Descarte listeners, assinaturas e temporizadores com o escopo responsável. Preserve os lockfiles Rust/Bun e as verificações obrigatórias de CI.</p><p>A instalação pelo usuário pertence ao <a href="./../user/installation.html">guia do usuário</a>. Essas verificações de desenvolvimento, sozinhas, não comprovam conectividade real com TikTok, renderização no OBS, compatibilidade com WebView nativa nem colaboração entre dois computadores.</p>',9)])])}const v=o(d,[["render",s]]);export{m as __pageData,v as default};
